defineSlots<{
  /** Accessible dialog title (visually hidden). Defaults to "Settings". */
  title?: () => any
  /** Accessible dialog description (visually hidden, for aria-describedby). */
  description?: () => any
  /** Sidebar + content panes (compose SettingsSidebar and SettingsContent). */
  default?: () => any
}>()

